    public function index(string$type):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$c=$this->config($type);if(!$c)return$this->notFound();$b=db_connect()->table($c['table'].' h')->select('h.*,s.'.$c['status_col'].',s.status_name')->join($c['status'].' s','s.id=h.status_id')->where('h.company_id',$this->company($u))->where('h.deleted_at',null);foreach(['project_id','site_id','supplier_id','status_id','transaction_type_id']as$f)if(ctype_digit((string)($this->request->getGet($f)??'')))$b->where('h.'.$f,(int)$this->request->getGet($f));$q=trim((string)($this->request->getGet('search')??''));if($q!=='')$b->like('h.'.$c['no'],$q);return$this->ok(ucwords(str_replace('-',' ',$type)).' retrieved successfully.',$c['list'],$b->orderBy('h.id','DESC')->get()->getResultArray());}
