    private function recalcPo(int$id):void{$s=db_connect()->table('material_purchase_order_items')->selectSum('taxable_amount')->selectSum('tax_amount')->selectSum('line_total')->where('purchase_order_id',$id)->where('deleted_at',null)->get()->getRowArray();$h=db_connect()->table('material_purchase_orders')->where('id',$id)->get()->getRowArray();$sub=(float)($s['taxable_amount']??0);$tax=(float)($s['tax_amount']??0);$grand=$sub+$tax+(float)$h['freight_amount']+(float)$h['round_off'];db_connect()->table('material_purchase_orders')->where('id',$id)->update(['subtotal'=>$sub,'taxable_amount'=>$sub,'tax_amount'=>$tax,'grand_total'=>$grand]);}
    private function approveRequestItems(int$id,object$u):void{$sid=$this->masterId('material_request_items_item_status_masters','item_status_code','APPROVED');db_connect()->table('material_request_items')->where('request_id',$id)->where('deleted_at',null)->set('approved_qty','requested_qty',false)->update(['item_status_id'=>$sid,'updated_by'=>(int)$u->id]);}
    private function syncRequestOrdering(int$poId,object$u):void{foreach(db_connect()->table('material_purchase_order_items')->where('purchase_order_id',$poId)->where('deleted_at',null)->get()->getResultArray()as$i){if(empty($i['request_item_id']))continue;$ri=db_connect()->table('material_request_items')->where('id',$i['request_item_id'])->where('deleted_at',null)->get()->getRowArray();if(!$ri)continue;$ordered=(float)$ri['ordered_qty']+(float)$i['ordered_qty'];$full=$ordered>=(float)$ri['approved_qty'];$sid=$this->masterId('material_request_items_item_status_masters','item_status_code',$full?'ORDERED':'PARTIALLY_ORDERED');db_connect()->table('material_request_items')->where('id',$ri['id'])->update(['ordered_qty'=>$ordered,'item_status_id'=>$sid,'updated_by'=>(int)$u->id]);$all=db_connect()->table('material_request_items')->select('COUNT(*) total,SUM(CASE WHEN ordered_qty >= approved_qty THEN 1 ELSE 0 END) complete')->where('request_id',$ri['request_id'])->where('deleted_at',null)->get()->getRowArray();$rcode=(int)$all['complete']===(int)$all['total']?'ORDERED':'PARTIALLY_ORDERED';$rs=$this->masterId('material_requests_status_masters','status_code',$rcode);db_connect()->table('material_requests')->where('id',$ri['request_id'])->update(['status_id'=>$rs,'updated_by'=>(int)$u->id]);}}
    private function syncPoReceipt(int$receiptId,object$u):void{$r=db_connect()->table('material_receipts')->where('id',$receiptId)->get()->getRowArray();if(empty($r['purchase_order_id']))return;foreach(db_connect()->table('material_receipt_items')->where('receipt_id',$receiptId)->where('deleted_at',null)->get()->getResultArray()as$i){if(empty($i['purchase_order_item_id']))continue;$po=db_connect()->table('material_purchase_order_items')->where('id',$i['purchase_order_item_id'])->get()->getRowArray();if(!$po)continue;$received=(float)$po['received_qty']+(float)$i['received_qty'];$accepted=(float)$po['accepted_qty']+(float)$i['accepted_qty'];$full=$received>=(float)$po['ordered_qty'];$sid=$this->masterId('material_purchase_order_items_item_status_masters','item_status_code',$full?'RECEIVED':'PARTIALLY_RECEIVED');db_connect()->table('material_purchase_order_items')->where('id',$po['id'])->update(['received_qty'=>$received,'accepted_qty'=>$accepted,'item_status_id'=>$sid,'updated_by'=>(int)$u->id]);}$all=db_connect()->table('material_purchase_order_items')->select('COUNT(*) total,SUM(CASE WHEN received_qty >= ordered_qty THEN 1 ELSE 0 END) complete')->where('purchase_order_id',$r['purchase_order_id'])->where('deleted_at',null)->get()->getRowArray();$code=(int)$all['complete']===(int)$all['total']?'RECEIVED':'PARTIALLY_RECEIVED';$sid=$this->masterId('material_purchase_orders_status_masters','status_code',$code);db_connect()->table('material_purchase_orders')->where('id',$r['purchase_order_id'])->update(['status_id'=>$sid,'updated_by'=>(int)$u->id]);}
    private function stockRows(int$c,int$p,?int$site,?int$mat):array{$postedR=$this->masterId('material_receipts_status_masters','status_code','POSTED');$postedT=$this->masterId('material_transactions_status_masters','status_code','POSTED');$db=db_connect();$rb=$db->table('material_receipt_items i')->select('i.material_id,r.site_id,SUM(i.accepted_qty) qty')->join('material_receipts r','r.id=i.receipt_id')->where(['i.company_id'=>$c,'i.project_id'=>$p,'r.status_id'=>$postedR])->where('i.deleted_at',null)->groupBy('i.material_id,r.site_id');if($site)$rb->where('r.site_id',$site);if($mat)$rb->where('i.material_id',$mat);$map=[];foreach($rb->get()->getResultArray()as$x)$map[$x['material_id'].':'.$x['site_id']]=(float)$x['qty'];$tb=$db->table('material_transaction_items i')->select('i.material_id,t.from_site_id,t.to_site_id,tt.transaction_type_code,SUM(i.quantity) qty')->join('material_transactions t','t.id=i.transaction_id')->join('material_transactions_transaction_type_masters tt','tt.id=t.transaction_type_id')->where(['i.company_id'=>$c,'i.project_id'=>$p,'t.status_id'=>$postedT])->where('i.deleted_at',null)->groupBy('i.material_id,t.from_site_id,t.to_site_id,tt.transaction_type_code');if($mat)$tb->where('i.material_id',$mat);foreach($tb->get()->getResultArray()as$x){$q=(float)$x['qty'];$m=(int)$x['material_id'];$code=$x['transaction_type_code'];if(in_array($code,['ISSUE','TRANSFER','ADJUSTMENT_OUT'],true)&&$x['from_site_id'])$map[$m.':'.$x['from_site_id']]=($map[$m.':'.$x['from_site_id']]??0)-$q;if(in_array($code,['RETURN','TRANSFER','ADJUSTMENT_IN'],true)&&$x['to_site_id'])$map[$m.':'.$x['to_site_id']]=($map[$m.':'.$x['to_site_id']]??0)+$q;} $out=[];foreach($map as$k=>$q){[$m,$s]=array_map('intval',explode(':',$k));if($site&&$s!==$site)continue;$mr=$db->table('materials')->select('material_code,material_name,base_uom_id,minimum_stock_qty,reorder_qty')->where('id',$m)->get()->getRowArray();$out[]=['project_id'=>$p,'site_id'=>$s,'material_id'=>$m]+$mr+['available_qty'=>round($q,4),'below_minimum'=>$q<(float)$mr['minimum_stock_qty']];}return$out;}
    private function config(string$t):?array{return$this->cfg[$t]??null;}private function statusCode(array$c,array$r):string{$x=db_connect()->table($c['status'])->select($c['status_col'])->where('id',$r['status_id'])->get()->getRowArray();return(string)($x[$c['status_col']]??'');}
    private function notify(string$type,array$record,string$action,int$actorId):void{try{(new MaterialNotificationService())->notify($type,$record,$action,$actorId);}catch(Throwable$e){log_message('error','Material notification processing failed: {error}',['error'=>$e->getMessage()]);}}
    private function headerFields(string$t):array{return match($t){'requests'=>['project_id','site_id','zone_id','request_no','request_date','required_by_date','priority_id','purpose'],'purchase-orders'=>['project_id','site_id','supplier_id','po_no','po_date','expected_delivery_date','delivery_address','payment_terms','freight_terms','discount_amount','freight_amount','round_off'],'receipts'=>['project_id','site_id','purchase_order_id','supplier_id','receipt_no','receipt_date','supplier_challan_no','supplier_challan_date','vehicle_no','invoice_no','invoice_date','remarks'],default=>['project_id','transaction_no','transaction_date','transaction_type_id','from_site_id','from_zone_id','to_site_id','to_zone_id','purpose','reference_type','reference_id','issued_by','received_by','remarks']};}
    private function itemFields(string$t):array{return match($t){'requests'=>['material_id','uom_id','requested_qty','approved_qty','ordered_qty','estimated_rate','specification_note','remarks'],'purchase-orders'=>['request_item_id','material_id','uom_id','ordered_qty','received_qty','accepted_qty','unit_rate','discount_percentage','gst_rate','specification'],'receipts'=>['purchase_order_item_id','material_id','uom_id','received_qty','accepted_qty','rejected_qty','unit_rate','batch_no','manufacture_date','expiry_date','quality_status_id','rejection_reason','storage_location'],default=>['material_id','uom_id','quantity','unit_rate','source_receipt_item_id','batch_no','work_description']};}
}
